@CrossOrigin
@RestController
@RequestMapping("/RiskQuery")
public class RiskQueryRestController extends BaseSpringRestController {
	
	public RiskQueryRestController( RiskService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Risk using a UUID
     * @param		UUID riskId
     * @return		Risk
     */    
    @GetMapping("/load")
    public Risk load( @RequestParam(required=true) UUID riskId ) {
    	Risk entity = null;

    	try {  
    		entity = service.getRisk( new RiskFetchOneSummary( riskId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Risk using Id " + riskId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Risk business objects
     * @return		Set<Risk>
     */
    @GetMapping("/")
    public List<Risk> loadAll() {                
    	List<Risk> riskList = null;
        
    	try {
            // load the Risk
            riskList = service.getAllRisk();
            
            if ( riskList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Risks" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Risks ", exc );
        	return null;
        }

        return riskList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Risk risk = null;
    protected RiskService service = null;
    private static final Logger LOGGER = Logger.getLogger(RiskQueryRestController.class.getName());
    
}
